insert into progetti (id, owner_id, titolo, descrizione, zona, stato, creato) values
  ('b303f7db-9d1d-4368-bd78-86507142ccef', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Rinfoltire fittonia', 'La pianta di fittonia ha filato a causa della posizione in cui si trova. L''obiettivo è di rinfoltire le due piantine.', 'casa / soggiorno', 'in_corso', '2026-07-24'),
  ('beeaf4ef-49a3-4898-9521-f7c2947a130d', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Albicocco', 'Far crescere un albicocco partendo da un seme', 'Casa / cucina', 'in_corso', '2026-07-28'),
  ('8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Orto Autunno-Inverno 2026-2027', '<p>Continuazione della stagione estiva. Lezioni dal primo anno: Nord-Ovest = massimo sole anche in autunno; Est/Sud-Est = ombra pomeridiana crescente in autunno; terreno di primo anno da strutturare con compost.</p><p>Nuova suddivisione dell''orto (5 x 3,5 m) in 4 zone da 4,375 m² ciascuna: Nord diviso in due fasce a tutta larghezza, Sud diviso in due meta'' affiancate. Nord-Rete (3,5 x 1,25 m) -&gt; piselli nani (Progress 9 Nano), fila unica da ~18 piante (20 cm sulla fila), tutore leggero (canna). Nord-Centro (3,5 x 1,25 m) -&gt; cavolo nero di Toscana, fila unica da ~8 piante (40 cm sulla fila). Sud-Est (1,75 x 2,5 m) -&gt; spinaci (Matador) a spaglio, 7 file da 1,75 m distanti 40 cm, semina fitta a 5 cm (profondita'' 1 cm) poi diradamento lasciando 1 pianta su 3, per ~84 piantine finali a 15 cm. Sud-Ovest (1,75 x 2,5 m) -&gt; cipolla (da seme), scalogno (da bulbi) e carote consociate: 11 file distanti 25 cm (6 file a 15 cm sulla fila: 3 cipolla Bianca di Maggio ~36 piante + 3 scalogno ~36 bulbi; 5 file di carote Berlicum 2 diradate a 5 cm, ~180 piantine).</p><p>Perche'' queste scelte: piselli nani al posto di romanesco e fave (non conveniva comprare semi per le poche piante che sarebbero entrate nello spazio residuo); spinaci spostati da Nord-Est a Sud-Est, dove l''ombra pomeridiana autunnale e'' piu'' marcata (li'' quest''estate c''erano le melanzane); scalogno reimpiantato nella stessa aiuola ma con lavorazione profonda per correggere il compattamento che ne ha impedito lo sviluppo quest''estate; carote consociate a cipolla/scalogno per il reciproco effetto repellente su mosca della carota e mosca della cipolla; cavolo nero di Toscana al posto della verza (semi introvabili), stessa specie (Brassica oleracea), stessa rusticita'' e tolleranza all''ombra parziale, raccolta a foglie scalare anziche'' in un unico taglio.</p><p>Lista acquisti: semi di carota Berlicum 2, cipolla Bianca di Maggio, spinacio Matador, pisello Progress 9 Nano e cavolo nero di Toscana (mix Il Mio Orto) già trovati in vivaio; bulbetti scalogno, compost, vassoio alveolato + substrato, canne leggere per i piselli.</p>', 'Orto', 'in_corso', '2026-07-28'),
  ('054b6add-ac0f-42cd-be96-cc71d029562a', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Arancio da pollone', 'Un pollone emesso dalla base del tronco dell''arancio navel è stato messo in acqua per tentare la radicazione, con l''obiettivo di ottenere una nuova pianta.<p><br></p><p>Aggiornamento del 6/8/26: il pollone era stato messo in vaso, ma dev''essere volato via con il vento 😅</p>', 'Crinale', 'fallito', '2026-07-30'),
  ('703401e6-37bc-492e-b4d8-9fb5561fc42b', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Rhyncospermum tricolore da talea', '<p>Talea di gelsomino tricolore (<i>Trachelospermum jasminoides</i> Tricolor, stessa specie del falso gelsomino già in Casa/Terrazzo soggiorno) messa in acqua per tentare la radicazione.<br><br>Aggiornamento 6/8/26: Talea marcita</p>', 'Casa / Terrazzo soggiorno', 'fallito', '2026-07-30');
insert into tappe (id, owner_id, progetto_id, data, descrizione, esito) values
  ('69af0579-8b6d-47a1-b9c4-36fb315bf41c', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'b303f7db-9d1d-4368-bd78-86507142ccef', '2026-07-26', 'Tagliate e interrate 2 talee di fittonia', 'riuscito'),
  ('b640a390-d6ba-4d6f-913c-1b81b3eafc3e', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'b303f7db-9d1d-4368-bd78-86507142ccef', '2026-08-02', 'Controlla ripresa talee (leggero tiro per verificare radicazione)', 'riuscito'),
  ('e49da242-f12d-4b24-8454-f1b352c8d024', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'b303f7db-9d1d-4368-bd78-86507142ccef', '2026-08-09', 'Verifica nuove foglioline sulle talee e nuovi getti laterali sulla pianta madre', 'riuscito'),
  ('dccd3785-91ef-4133-8f2d-18e02c3535d3', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'beeaf4ef-49a3-4898-9521-f7c2947a130d', '2026-07-24', 'Nocciolo pulito messo a germogliare in un tovagliolo umido, dentro un sacchetto ermetico, al buio, a temperatura ambiente', 'riuscito'),
  ('6273d2fa-c686-41fc-805e-68ff653ff5b4', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'beeaf4ef-49a3-4898-9521-f7c2947a130d', '2026-08-07', 'Primo controllo: verificare che il tovagliolo sia ancora umido (non zuppo, niente muffa) e ispezionare la comparsa di una radichetta', 'atteso'),
  ('216a7976-636a-461c-837f-993f84470b58', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'beeaf4ef-49a3-4898-9521-f7c2947a130d', '2026-08-21', 'Secondo controllo: se è comparsa la radichetta, seminare subito il nocciolo in vaso con terriccio drenante (radichetta verso il basso, 2-3 cm di profondità); altrimenti continuare il monitoraggio', 'atteso'),
  ('702810ab-438a-44c0-a561-34f4e15c678c', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'beeaf4ef-49a3-4898-9521-f7c2947a130d', '2026-09-04', 'Se dopo circa 6 settimane a temperatura ambiente non c''è ancora germinazione, il nocciolo probabilmente necessita di un periodo di freddo per rompere la dormienza: spostare il sacchetto nello scomparto verdure del frigorifero per 6-8 settimane a 3-5°C, mantenendo l''umidità', 'atteso'),
  ('011a52e1-ffda-4062-9b98-1832214036f9', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'beeaf4ef-49a3-4898-9521-f7c2947a130d', '2026-10-30', 'Fine dell''eventuale stratificazione a freddo: controllare di nuovo la comparsa della radichetta e seminare non appena si presenta', 'atteso'),
  ('a1dfb9ae-16b0-4e5e-ade3-c7e8b82e6ad3', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'beeaf4ef-49a3-4898-9521-f7c2947a130d', '2026-12-15', 'Verifica generale della germinazione: se a questo punto non è ancora spuntato nulla dal terreno, riprovare con un nuovo seme stratificato in inverno per semina a fine inverno', 'atteso'),
  ('99c09f24-ef0d-42e0-9736-01580fa1b2fc', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'beeaf4ef-49a3-4898-9521-f7c2947a130d', '2027-04-01', 'Prima crescita della piantina in vaso: luce abbondante, irrigazione regolare senza ristagni, protezione dalle ultime gelate tardive', 'atteso'),
  ('b8cb28c2-5eb4-449c-89ac-0b26b6bc2e2a', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'beeaf4ef-49a3-4898-9521-f7c2947a130d', '2027-10-15', 'Dopo il primo anno e a pianta ormai a riposo, travasare in vaso più grande o mettere a dimora in piena terra in zona soleggiata e riparata dal vento (es. Est o Crinale)', 'atteso'),
  ('9d002ec7-53d6-4e01-bfa6-108daf406adf', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'beeaf4ef-49a3-4898-9521-f7c2947a130d', '2029-07-01', 'Prime fioriture/fruttificazioni non attese prima di 3-5 anni dalla semina. Nota: un albicocco da seme non garantisce frutti identici alla pianta madre — per frutti affidabili valutare l''innesto su portainnesto quando la pianta ha 1-2 anni', 'atteso'),
  ('d3f2a965-0b80-4e94-8bc6-e120b892df99', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-07-31', 'Semina in semenzaio di cavolo nero di Toscana (~8 piante), vassoio alveolato in balcone ombreggiato — germina in 5-7 giorni', 'riuscito'),
  ('e20c1448-d3f9-4c7a-a1ff-07abe0132f16', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-07-31', 'Decidere se piantare la zucca in vaso fuori dall''orto (occupa 2-3 m di raggio, altrimenti si rinuncia)', 'riuscito'),
  ('1ac951b9-7af4-4dbd-a8f5-9078470b4915', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-08-10', 'Semina in semenzaio dei piselli nani Progress 9 Nano (~18 piante); preparare le canne leggere come tutore prima del trapianto', 'riuscito'),
  ('d160a8c3-93f1-4c12-8d38-f71bff7fcb0f', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-08-20', 'Preparazione del terreno in Sud-Ovest: rimozione residui delle piante estive (zucchine/scalogno), 2-3 kg/m² di compost maturo, lavorazione profonda (25-30 cm) per correggere il compattamento', 'atteso'),
  ('fee774de-52fe-4b68-aab7-71e8eeada594', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-08-25', 'Semina diretta dei semi di cipolla Bianca di Maggio nelle 3 file dedicate di Sud-Ovest (distanti 25 cm, schema a file alternate)', 'atteso'),
  ('a027ac07-a0c7-43aa-8198-7f8cd989dd3d', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-08-28', 'Travaso del cavolo nero di Toscana in un vaso più grande (i vasetti 6x6x8 cm attuali non basterebbero fino al trapianto di ottobre senza strozzare le radici)', 'riuscito'),
  ('2f611a64-a518-4ea0-8e53-1dbc93c2d918', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-09-22', 'Semina diretta delle carote Berlicum 2 nelle 5 file rimanenti di Sud-Ovest, da diradare poi a 5 cm (~180 piantine finali)', 'atteso'),
  ('ddd322a8-c713-4c6c-add8-cb86af90af6b', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-09-30', 'Semina diretta a spaglio dello spinacio Matador in Sud-Est (rimandata da metà agosto per lasciar posto alle melanzane ancora produttive): 7 file da 1,75 m distanti 40 cm, semi a 5 cm sulla fila, profondità 1 cm; dopo la germinazione diradare lasciando 1 piantina su 3 (spaziatura finale ~15 cm, ~84 piantine finali)', 'atteso'),
  ('4009267a-ad9d-4c69-a53b-0c267286b563', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-10-06', 'Trapianto in campo: cavolo nero di Toscana (~8 piante, Nord-Centro, 40 cm) e piselli nani Progress 9 Nano (~18 piante, Nord-Rete, 20 cm, con canne leggere come tutore) — rimandato da metà settembre per tenere più a lungo possibile i pomodori cuore di bue, danneggiati da grandine ma ancora con frutti da far maturare', 'atteso'),
  ('3cbdc57e-4a4e-4332-b4ba-872174149f01', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-10-05', 'Diradamento delle cipolle Bianca di Maggio, lasciando le piantine a 15 cm sulla fila (~36 piante)', 'atteso'),
  ('cad09bce-2c28-444a-ac60-2c2ef26ce940', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-10-15', 'Reimpianto bulbetti freschi di scalogno nelle 3 file dedicate di Sud-Ovest (~36 bulbi, 15 cm sulla fila)', 'atteso'),
  ('51d8cd2f-a74d-4d95-ac4e-fe890ca84775', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-11-10', 'Prima raccolta spinaci (taglio scalare, prima le foglie esterne)', 'atteso'),
  ('c04b110f-359b-416e-99e4-2d9388d50ed8', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-11-20', 'Prima raccolta cavolo nero di Toscana (più dolce dopo le prime gelate, prosegue fino a gennaio)', 'atteso'),
  ('b4161e99-63ee-406c-afd8-d1c661ea368e', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2026-12-20', 'Raccolta carote (~180)', 'atteso'),
  ('203ed34c-36a8-40fe-8a2f-d448b030995b', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2027-04-20', 'Raccolta piselli nani (quando il baccello è turgido)', 'atteso'),
  ('16f5fd61-3924-42c6-806a-9f84a0248046', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2027-05-15', 'Raccolta cipolle (quando le foglie iniziano ad appassire)', 'atteso'),
  ('6eccfb0e-b6aa-43c8-945a-d30fa8c41042', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '8edc4fc8-1e5a-46f2-ae9e-e1ef04f8dc5c', '2027-06-10', 'Raccolta scalogno', 'atteso'),
  ('d63bcfaf-ff57-42a2-9b4a-1dc537fb5019', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '054b6add-ac0f-42cd-be96-cc71d029562a', '2026-07-30', 'Pollone prelevato dalla base del tronco dell''arancio navel, messo in acqua in attesa di radicazione', 'riuscito'),
  ('b9bb3193-5eff-4a89-b058-1a9917f9434e', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '054b6add-ac0f-42cd-be96-cc71d029562a', '2026-07-30', 'Confermato dall''utente: il pollone è nato sotto il punto d''innesto, dal portainnesto — quindi NON produrrà arance navel se radicato, ma la pianta del portainnesto (specie non nota con certezza: comunemente arancio trifogliato, citrange, arancio amaro o Citrus volkameriana)', 'riuscito'),
  ('51482d63-ad7b-48cb-800a-39ed852e5a3c', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '054b6add-ac0f-42cd-be96-cc71d029562a', '2026-08-06', 'Cambiare l''acqua ogni 3-4 giorni per evitare marciumi; controllare che la base dello stelo resti soda, senza rammollimenti né cattivo odore', 'atteso'),
  ('9da8ceda-1d76-498c-9302-89e60de6617c', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '054b6add-ac0f-42cd-be96-cc71d029562a', '2026-08-20', 'Se non sono ancora comparse radici, valutare il passaggio a un substrato drenante (sabbia/perlite) con ormone radicante in polvere/gel: gli agrumi radicano con difficoltà in sola acqua e rischiano marciumi se lasciati sommersi troppo a lungo', 'atteso'),
  ('473c14bc-d544-49cf-9947-827a9fa7e845', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '054b6add-ac0f-42cd-be96-cc71d029562a', '2026-09-24', 'Controllo finale della radicazione: se sono presenti radici di almeno 2-3 cm, travasare in vaso con terriccio drenante specifico per agrumi; se dopo 8 settimane non c''è nulla, il tentativo va considerato non riuscito (radicazione spontanea degli agrumi da pollone/talea è tutt''altro che garantita)', 'atteso'),
  ('8a8428dc-ed63-4bdf-a9f5-83886a191582', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '054b6add-ac0f-42cd-be96-cc71d029562a', '2027-03-15', 'Se radicato con successo, mettere a dimora in vaso capiente o in piena terra a inizio primavera, in posizione soleggiata e riparata dal vento freddo (le piante giovani di agrumi sono più sensibili al gelo dei soggetti adulti)', 'atteso'),
  ('ff65d7e2-0b72-42ed-b0b7-54bf0bc6a892', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '703401e6-37bc-492e-b4d8-9fb5561fc42b', '2026-07-30', 'Rametto di gelsomino tricolore messo in acqua in attesa di radicazione', 'fallito'),
  ('0c77c3cb-88a1-4b88-a5e2-21355b93aad5', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '703401e6-37bc-492e-b4d8-9fb5561fc42b', '2026-08-06', 'Cambiare l''acqua ogni 3-4 giorni, tenere in luogo luminoso senza sole diretto; rimuovere eventuali foglie sommerse per evitare marciumi', 'fallito'),
  ('ca1688b1-5e92-45fa-b2f7-2b98ab2e9b0e', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '703401e6-37bc-492e-b4d8-9fb5561fc42b', '2026-08-13', 'Primo controllo radicazione: il falso gelsomino radica con relativa facilità, le prime radichette bianche filiformi possono comparire già dopo 2-3 settimane', 'atteso'),
  ('ff86c1f4-a840-46fb-97ef-1e4e1b741ea0', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '703401e6-37bc-492e-b4d8-9fb5561fc42b', '2026-08-27', 'Se sono presenti radici di 2-3 cm, travasare in vaso con terriccio drenante; se non c''è ancora nulla, valutare un taglio fresco alla base della talea e l''uso di ormone radicante', 'atteso'),
  ('404360f8-672d-4dca-abed-ddfd79f11825', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', '703401e6-37bc-492e-b4d8-9fb5561fc42b', '2026-09-24', 'Verifica ripresa dopo il travaso: la comparsa di nuove foglioline conferma che la pianta si è ambientata al terriccio', 'atteso');
insert into concimi (id, owner_id, nome, npk, disponibile, descrizione) values
  ('fdc43b59-cfb4-4d28-bf7c-a33b71191856', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Bottos Sprint N', '{"n":27,"p":0,"k":14}'::jsonb, true, null),
  ('0b3eb571-814a-49f6-b124-9c70f9a7f3c8', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Bottos Summer K', '{"n":10,"p":0,"k":30}'::jsonb, true, null),
  ('b4e2a638-0b51-4932-abc2-c3848d0fa03c', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Bottos Autumn K', '{"n":21,"p":0,"k":25}'::jsonb, true, null),
  ('449e2713-6c3f-440a-bf88-1db602034ddd', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Cifo Asso di Fiori', '{"n":20,"p":20,"k":20}'::jsonb, true, null),
  ('f0df2766-11e1-4faf-908e-4fb8a7a99fc7', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'DueCI Concime Azalee e Rododendri', '{"n":5,"p":5,"k":7}'::jsonb, false, null),
  ('1c427b76-79c6-45f3-a6a0-71246fb70eec', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Fatto in casa - Acqua di buccia di banana (macerato)', '{"n":1,"p":3,"k":8}'::jsonb, true, 'Metti 2-3 bucce di banana a pezzi in un litro d''acqua, lascia macerare 2-3 giorni a temperatura ambiente mescolando ogni tanto, poi filtra. Usa il liquido puro per innaffiare, senza ulteriore diluizione.'),
  ('d1ea0e82-07eb-4c84-b37c-1b75eb38356b', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Fatto in casa - Fondi di caffè (macerato)', '{"n":10,"p":2,"k":4}'::jsonb, false, 'Metti in infusione una tazza di fondi di caffè esausti (freddi) in un litro d''acqua per 2-3 giorni, mescolando di tanto in tanto, poi filtra. Diluisci il liquido 1:1 con acqua prima di innaffiare.'),
  ('0076d75d-47ec-4775-904a-6b82f02ad305', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Fatto in casa - Macerato di ortica', '{"n":8,"p":2,"k":4}'::jsonb, false, 'Riempi un contenitore con ortica fresca tritata (circa 1 kg per 10 litri d''acqua) e lascia macerare 1-2 settimane, mescolando ogni giorno; è pronto quando smette di fare schiuma. Filtra e diluisci 1:10 con acqua prima dell''uso. Attenzione all''odore forte durante la fermentazione: tienilo lontano da casa.'),
  ('4eb40d68-13bf-4a29-88ec-76ee03a35a90', 'fc227422-ece8-4dca-b706-956ec7ca9e6e', 'Fatto in casa - Acqua di cottura verdure', '{"n":2,"p":1,"k":4}'::jsonb, true, 'Riutilizza l''acqua di cottura di verdure (non salata), lasciata raffreddare a temperatura ambiente. Usala pura per innaffiare, senza bisogno di diluizione o macerazione.'),
